<?php
namespace App\Console\Commands;use App\Models\NewsSource;use App\Services\News\NewsFetcherService;use Illuminate\Console\Command;use Illuminate\Support\Facades\Log;
class FetchLatestNews extends Command{protected $signature='news:fetch {--source= : Fetch one source name} {--limit= : Maximum sources to fetch}';protected $description='Fetch and normalize news without persisting articles';public function handle(NewsFetcherService $fetcher):int{$query=NewsSource::where('is_active',true)->where(fn($q)=>$q->whereNotNull('feed_url')->orWhereNotNull('api_url'))->orderByDesc('priority');$query->when($this->option('source'),fn($q,$v)=>$q->where('name',$v))->when($this->option('limit'),fn($q,$v)=>$q->limit(max(1,(int)$v)));$sources=$query->get();$this->info("Processing {$sources->count()} sources...");$total=0;foreach($sources as $source){try{$this->line("Fetching: {$source->name}");$articles=$fetcher->fetch($source);$total+=count($articles);$source->update(['last_fetched_at'=>now(),'last_fetch_status'=>'success','last_error'=>null]);$this->info('Found '.count($articles).' normalized articles');}catch(\Throwable $e){$source->update(['last_fetched_at'=>now(),'last_fetch_status'=>'failed','last_error'=>$e->getMessage()]);Log::error('News source fetch failed',['source'=>$source->name,'error'=>$e->getMessage()]);$this->error($source->name.': '.$e->getMessage());}}$this->info("Total normalized: {$total}. No articles saved.");return self::SUCCESS;}}
